//go:build integration

// Package integration contains integration tests for the CLI.
//
// This file contains explicit contract tests for hook input JSON schemas.
// These tests document and enforce the expected structure of stdin input
// for each hook type. If the refactor changes these contracts, these tests
// will fail - which is the desired behavior.
package integration

import (
	"bytes"
	"encoding/json"
	"os/exec"
	"testing"
)

// =============================================================================
// Claude Code Hook Contracts
// =============================================================================

// ClaudeSessionHookInput documents the expected JSON schema for Claude Code
// session lifecycle hooks (session-start, session-end, stop).
type ClaudeSessionHookInput struct {
	SessionID      string `json:"session_id"`
	TranscriptPath string `json:"transcript_path"`
}

// ClaudeUserPromptSubmitInput documents the expected JSON schema for Claude Code
// user-prompt-submit hook.
type ClaudeUserPromptSubmitInput struct {
	SessionID      string `json:"session_id"`
	TranscriptPath string `json:"transcript_path"`
	Prompt         string `json:"prompt,omitempty"`
}

// ClaudePreTaskInput documents the expected JSON schema for Claude Code
// pre-task hook (PreToolUse with Task matcher).
type ClaudePreTaskInput struct {
	SessionID      string                 `json:"session_id"`
	TranscriptPath string                 `json:"transcript_path"`
	ToolUseID      string                 `json:"tool_use_id"`
	ToolInput      map[string]interface{} `json:"tool_input"`
}

// ClaudePostTaskInput documents the expected JSON schema for Claude Code
// post-task hook (PostToolUse with Task matcher).
type ClaudePostTaskInput struct {
	SessionID      string                 `json:"session_id"`
	TranscriptPath string                 `json:"transcript_path"`
	ToolUseID      string                 `json:"tool_use_id"`
	ToolInput      map[string]interface{} `json:"tool_input"`
	ToolResponse   ClaudeTaskResponse     `json:"tool_response"`
}

// ClaudeTaskResponse documents the tool_response structure for post-task.
type ClaudeTaskResponse struct {
	AgentID string `json:"agentId"`
}

// ClaudePostTodoInput documents the expected JSON schema for Claude Code
// post-todo hook (PostToolUse with TodoWrite matcher).
type ClaudePostTodoInput struct {
	SessionID      string                 `json:"session_id"`
	TranscriptPath string                 `json:"transcript_path"`
	ToolName       string                 `json:"tool_name"`
	ToolUseID      string                 `json:"tool_use_id"`
	ToolInput      ClaudeTodoToolInput    `json:"tool_input"`
	ToolResponse   map[string]interface{} `json:"tool_response"`
}

// ClaudeTodoToolInput documents the tool_input structure for post-todo.
type ClaudeTodoToolInput struct {
	Todos []ClaudeTodoItem `json:"todos"`
}

// ClaudeTodoItem documents a single todo item in the TodoWrite input.
type ClaudeTodoItem struct {
	Content    string `json:"content"`
	Status     string `json:"status"`
	ActiveForm string `json:"activeForm"`
}

// =============================================================================
// Gemini CLI Hook Contracts
// =============================================================================

// GeminiSessionHookInput documents the expected JSON schema for Gemini CLI
// session lifecycle hooks (session-start, session-end).
type GeminiSessionHookInput struct {
	SessionID      string `json:"session_id"`
	TranscriptPath string `json:"transcript_path"`
	Cwd            string `json:"cwd"`
	HookEventName  string `json:"hook_event_name"`
	Timestamp      string `json:"timestamp"`
	Source         string `json:"source,omitempty"` // SessionStart only
	Reason         string `json:"reason,omitempty"` // SessionEnd only
}

// GeminiAgentHookInput documents the expected JSON schema for Gemini CLI
// agent hooks (before-agent, after-agent).
type GeminiAgentHookInput struct {
	SessionID      string `json:"session_id"`
	TranscriptPath string `json:"transcript_path"`
	Cwd            string `json:"cwd"`
	HookEventName  string `json:"hook_event_name"`
	Timestamp      string `json:"timestamp"`
	Prompt         string `json:"prompt,omitempty"` // BeforeAgent only
}

// GeminiToolHookInput documents the expected JSON schema for Gemini CLI
// tool hooks (before-tool, after-tool).
type GeminiToolHookInput struct {
	SessionID      string                 `json:"session_id"`
	TranscriptPath string                 `json:"transcript_path"`
	Cwd            string                 `json:"cwd"`
	HookEventName  string                 `json:"hook_event_name"`
	Timestamp      string                 `json:"timestamp"`
	ToolName       string                 `json:"tool_name"`
	ToolInput      map[string]interface{} `json:"tool_input"`
	ToolResponse   map[string]interface{} `json:"tool_response,omitempty"` // AfterTool only
}

