// TestContract_ClaudeCode_UserPromptSubmit verifies the user-prompt-submit hook
// accepts the documented JSON schema and processes it correctly.
func TestContract_ClaudeCode_UserPromptSubmit(t *testing.T) {
	t.Parallel()
	env := NewTestEnv(t)
	defer env.Cleanup()

	env.InitRepo()
	env.WriteFile("README.md", "# Test")
	env.GitAdd("README.md")
	env.GitCommit("Initial commit")
	env.GitCheckoutNewBranch("feature/test")
	env.InitEntire("manual-commit")

	// This is the contract: user-prompt-submit expects this exact structure
	input := ClaudeUserPromptSubmitInput{
		SessionID:      "contract-test-session",
		TranscriptPath: "", // Can be empty for user-prompt-submit
		Prompt:         "Test prompt for contract verification",
	}

	inputJSON, err := json.Marshal(input)
	if err != nil {
		t.Fatalf("Failed to marshal contract input: %v", err)
	}

	cmd := exec.Command(getTestBinary(), "hooks", "claude-code", "user-prompt-submit")
	cmd.Dir = env.RepoDir
	cmd.Stdin = bytes.NewReader(inputJSON)
	cmd.Env = env.CommandEnv()

	output, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("Contract violation: user-prompt-submit hook rejected valid input\nInput: %s\nError: %v\nOutput: %s",
			inputJSON, err, output)
	}
}

// TestContract_ClaudeCode_Stop verifies the stop hook accepts the documented
// JSON schema and creates a checkpoint when there are file changes.
func TestContract_ClaudeCode_Stop(t *testing.T) {
	t.Parallel()
	env := NewTestEnv(t)
	defer env.Cleanup()

	env.InitRepo()
	env.WriteFile("README.md", "# Test")
	env.GitAdd("README.md")
	env.GitCommit("Initial commit")
	env.GitCheckoutNewBranch("feature/test")
	env.InitEntire("manual-commit")

	session := env.NewSession()

	// First, submit a prompt to initialize session state
	promptInput := ClaudeUserPromptSubmitInput{
		SessionID:      session.ID,
		TranscriptPath: session.TranscriptPath,
	}
	promptJSON, _ := json.Marshal(promptInput)

	promptCmd := exec.Command(getTestBinary(), "hooks", "claude-code", "user-prompt-submit")
	promptCmd.Dir = env.RepoDir
	promptCmd.Stdin = bytes.NewReader(promptJSON)
	promptCmd.Env = env.CommandEnv()
	if output, err := promptCmd.CombinedOutput(); err != nil {
		t.Fatalf("user-prompt-submit failed: %v\nOutput: %s", err, output)
	}

	// Create a file change and transcript
	env.WriteFile("test.txt", "contract test content")
	session.CreateTranscript("Contract test prompt", []FileChange{
		{Path: "test.txt", Content: "contract test content"},
	})

	// This is the contract: stop expects this exact structure
	input := ClaudeSessionHookInput{
		SessionID:      session.ID,
		TranscriptPath: session.TranscriptPath,
	}

	inputJSON, err := json.Marshal(input)
	if err != nil {
		t.Fatalf("Failed to marshal contract input: %v", err)
	}

	cmd := exec.Command(getTestBinary(), "hooks", "claude-code", "stop")
	cmd.Dir = env.RepoDir
	cmd.Stdin = bytes.NewReader(inputJSON)
	cmd.Env = env.CommandEnv()

	output, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("Contract violation: stop hook rejected valid input\nInput: %s\nError: %v\nOutput: %s",
			inputJSON, err, output)
	}

	// Verify a checkpoint was created (observable outcome)
	points := env.GetRewindPoints()
	if len(points) != 1 {
		t.Errorf("Contract violation: stop hook should create exactly 1 rewind point, got %d", len(points))
	}
}

